namespace{template<class S,class V>bool SampleTrack(const CKeyFrameTrack<S,V>&track,CAnim&a,V&out,CKeyTrackStatus*status=nullptr){unsigned sequence=a.primarySeq;int time=sequence<a.seq.size()?a.seq[sequence].elapsed:0;if(track.m_globalSeqId!=~0U){sequence=0;if(track.m_globalSeqId<a.globalSeqElapsed.size())time=static_cast<int>(a.globalSeqElapsed[track.m_globalSeqId]);}return track.Interpolate(sequence,time,out,status);}}
void TransformObjectView(CAnim&a,CAnimObj&o){if(o.animObjId>=a.status.size())return;auto&s=a.status[o.animObjId];NTempest::C3Vector t{},scale{1};NTempest::C4Quaternion r;bool ht=SampleTrack(o.translation,a,t,&s.translation),hr=SampleTrack(o.rotation,a,r,&s.rotation),hs=SampleTrack(o.scale,a,scale,&s.scale);const NTempest::C3Vector pivot=a.hdata&&o.animObjId<a.hdata->pivots.size()?a.hdata->pivots[o.animObjId]:NTempest::C3Vector{};NTempest::C34Matrix m;if(o.parent&&o.parent->animObjId<a.status.size())m=a.status[o.parent->animObjId].transform;m.Translate(pivot);if(ht)m.Translate(t);if(hr)m.Rotate(r);if(s.faceDir&&o.animObjId<a.lookAtTarget.size())ApplyFaceDir(m,a.lookAtTarget[o.animObjId]);if(hs)m.Scale(scale);m.Translate({-pivot.x,-pivot.y,-pivot.z});s.transform=m;if(auto*model=dynamic_cast<CAnimModelObj*>(&o)){float visibility=1.0F;SampleTrack(model->visibility,a,visibility);s.visible=visibility>0.0F;}}
namespace{bool EventKeyPassed(const CAnim&a,const CAnimSequence&sequence,int key){const int now=a.seq[a.primarySeq].elapsed,prev=static_cast<int>(a.seqLastTime);if(a.seqLastAdvance>=0)return a.sequenceWrapped?((key>prev&&key<=sequence.end)||(key>=sequence.start&&key<=now)):(key>prev&&key<=now);return a.sequenceWrapped?((key<prev&&key>=sequence.start)||(key<=sequence.end&&key>=now)):(key<prev&&key>=now);}}
void PlaceObject(CAnim&a,CAnimObj&o){TransformObjectView(a,o);if(auto*light=dynamic_cast<CAnimLightObj*>(&o))SetLightValues(a,*light);else if(auto*emitter=dynamic_cast<CAnimEmitter2Obj*>(&o))SetEmitter2Values(a,*emitter);else if(auto*ribbon=dynamic_cast<CAnimRibbonObj*>(&o))SetRibbonValues(a,*ribbon);for(auto*c:o.childarray)if(c)PlaceObject(a,*c);}void PrepareObjectHierarchyViews(CAnim&a){if(!a.hdata)return;for(auto*o:a.hdata->headarray)if(o)PlaceObject(a,*o);}void AnimProcessEvents(CAnim&a){if(!a.hdata||!a.appEvent||a.primarySeq>=a.seq.size()||a.primarySeq>=a.hdata->seq.size())return;const auto&sequence=a.hdata->seq[a.primarySeq];for(auto*base:a.hdata->obj){if(!base||base->type!=ANIM_OBJ_EVENT)continue;auto&e=*static_cast<CAnimEventObj*>(base);const CKeySeq range=a.primarySeq<e.events.m_indices.size()?e.events.m_indices[a.primarySeq]:CKeySeq{0,static_cast<unsigned>(e.events.m_keyFrames.size())};const unsigned end=(std::min)(range.start+range.count,static_cast<unsigned>(e.events.m_keyFrames.size()));for(unsigned k=range.start;k<end;++k)if(EventKeyPassed(a,sequence,e.events.m_keyFrames[k].time)&&e.animObjId<a.status.size())a.appEvent(e.name,a.status[e.animObjId].transform*NTempest::C3Vector{});}}
void IAnimAnimateModel(CAnim&a){AnimateAllTextureMaps(a);AnimateAllGeosets(a);AnimateAllMaterialLayers(a);PrepareObjectHierarchyViews(a);AnimProcessEvents(a);}void AnimAnimateModel(CAnim&a){IAnimAnimateModel(a);}
void ISetSequenceUnchanged(CAnim&a){if(a.primarySeq<a.seq.size())a.seq[a.primarySeq].seqFinished=false;}void ISetEventSequenceUnchanged(CAnim&a){a.sequenceWrapped=false;}void IProcessEvent(CAnim&a,CAnimEventObj&e){if(!a.appEvent||!a.hdata||a.primarySeq>=a.seq.size()||a.primarySeq>=a.hdata->seq.size())return;for(const auto&key:e.events.m_keyFrames)if(EventKeyPassed(a,a.hdata->seq[a.primarySeq],key.time)){NTempest::C3Vector p{};if(e.animObjId<a.status.size()){const auto&m=a.status[e.animObjId].transform;p={m.d0,m.d1,m.d2};}a.appEvent(e.name,p);}}void PlaceEventObject(CAnim&a,CAnimEventObj&o){TransformObjectView(a,o);IProcessEvent(a,o);}void PlaceModelObject(CAnim&a,CAnimModelObj&o){TransformObjectView(a,o);if(o.animObjId<a.status.size()&&a.primarySeq<a.seq.size()){float visible=1;o.visibility.Interpolate(a.primarySeq,a.seq[a.primarySeq].elapsed,visible);a.status[o.animObjId].visible=visible>0;}}
CGeosetColor CalcGeosetColor(CAnim&a,CAnimGeoset&g){CGeosetColor out;C3Color color{1,1,1};SampleTrack(g.color,a,color);out.color={color.r,color.g,color.b};SampleTrack(g.visibility,a,out.alpha);return out;}void SetGeosetColor(CAnim&a,unsigned i,const C3Color&c){if(i>=a.geosetStatus.size())a.geosetStatus.resize(i+1);a.geosetStatus[i].color={c.r,c.g,c.b};}void SetGeosetAlpha(CAnim&a,unsigned i,float v){if(i>=a.geosetStatus.size())a.geosetStatus.resize(i+1);a.geosetStatus[i].alpha=std::clamp(v,0.0F,1.0F);}
CAnimLightValues SetLightValues(CAnim&a,CAnimLightObj&o){CAnimLightValues v;v.type=o.lightType;v.attenuationStart=o.baseAttenStart;v.attenuationEnd=o.baseAttenEnd;v.intensity=o.baseIntensity;v.ambientIntensity=o.baseAmbientIntensity;v.color=o.baseColor;v.ambientColor=o.baseAmbientColor;SampleTrack(o.attenstart,a,v.attenuationStart);SampleTrack(o.attenend,a,v.attenuationEnd);SampleTrack(o.intensity,a,v.intensity);SampleTrack(o.ambIntensity,a,v.ambientIntensity);SampleTrack(o.visibility,a,v.visibility);SampleTrack(o.color,a,v.color);SampleTrack(o.ambColor,a,v.ambientColor);if(o.animObjId<a.status.size()){const auto&m=a.status[o.animObjId].transform;const NTempest::C3Vector pivot=a.hdata&&o.animObjId<a.hdata->pivots.size()?a.hdata->pivots[o.animObjId]:NTempest::C3Vector{};v.position=m*pivot;v.direction={-m.c0,-m.c1,-m.c2};}if(o.animObjId>=a.lightStatus.size())a.lightStatus.resize(o.animObjId+1);a.lightStatus[o.animObjId]=v;return v;}
CAnimEmitter2Values SetEmitter2Values(CAnim&a,CAnimEmitter2Obj&o){CAnimEmitter2Values v;SampleTrack(o.particleSpeed,a,v.speed);SampleTrack(o.emissionRate,a,v.emissionRate);SampleTrack(o.gravity,a,v.gravity);SampleTrack(o.variation,a,v.variation);SampleTrack(o.latitude,a,v.latitude);SampleTrack(o.longitude,a,v.longitude);SampleTrack(o.length,a,v.length);SampleTrack(o.width,a,v.width);SampleTrack(o.zsource,a,v.zsource);SampleTrack(o.lifeSpan,a,v.lifeSpan);SampleTrack(o.visibility,a,v.visibility);if(o.animObjId>=a.emitter2Status.size())a.emitter2Status.resize(o.animObjId+1);a.emitter2Status[o.animObjId]=v;return v;}
CAnimRibbonValues SetRibbonValues(CAnim&a,CAnimRibbonObj&o){CAnimRibbonValues v;SampleTrack(o.heightAbove,a,v.heightAbove);SampleTrack(o.heightBelow,a,v.heightBelow);SampleTrack(o.alpha,a,v.alpha);SampleTrack(o.visibility,a,v.visibility);SampleTrack(o.slot,a,v.slot);SampleTrack(o.color,a,v.color);if(o.animObjId>=a.ribbonStatus.size())a.ribbonStatus.resize(o.animObjId+1);a.ribbonStatus[o.animObjId]=v;return v;}
void SetLightColor(CAnim&a,unsigned i,const C3Color&v){if(i>=a.lightStatus.size())a.lightStatus.resize(i+1);a.lightStatus[i].color=v;}void SetLightIntensity(CAnim&a,unsigned i,float v){if(i>=a.lightStatus.size())a.lightStatus.resize(i+1);a.lightStatus[i].intensity=(std::max)(0.0F,v);}void SetLightDirection(CAnim&a,unsigned i,const NTempest::C3Vector&v){if(i>=a.lightStatus.size())a.lightStatus.resize(i+1);a.lightStatus[i].direction=v;}void SetEmitterLength2(CAnim&a,unsigned i,float v){if(i>=a.emitter2Status.size())a.emitter2Status.resize(i+1);a.emitter2Status[i].length=v;}void SetEmitterWidth2(CAnim&a,unsigned i,float v){if(i>=a.emitter2Status.size())a.emitter2Status.resize(i+1);a.emitter2Status[i].width=v;}void SetEmitterZsource2(CAnim&a,unsigned i,float v){if(i>=a.emitter2Status.size())a.emitter2Status.resize(i+1);a.emitter2Status[i].zsource=v;}void SetEmitterLifeSpan2(CAnim&a,unsigned i,float v){if(i>=a.emitter2Status.size())a.emitter2Status.resize(i+1);a.emitter2Status[i].lifeSpan=(std::max)(0.0F,v);}void SetRibbonTexSlot(CAnim&a,unsigned i,unsigned v){if(i>=a.ribbonStatus.size())a.ribbonStatus.resize(i+1);a.ribbonStatus[i].slot=v;}
