void AnimateCamera(CAnim&a,unsigned i){if(!a.hdata||i>=a.hdata->cameraObjs.size()||a.primarySeq>=a.seq.size())return;auto&c=a.hdata->cameraObjs[i];NTempest::C3Vector t{};float roll=0,visibility=1;c.translation.Interpolate(a.primarySeq,a.seq[a.primarySeq].elapsed,t);c.roll.Interpolate(a.primarySeq,a.seq[a.primarySeq].elapsed,roll);c.visibility.Interpolate(a.primarySeq,a.seq[a.primarySeq].elapsed,visibility);if(i>=a.lookAtTarget.size())a.lookAtTarget.resize(i+1);if(i>=a.cameraVisibility.size())a.cameraVisibility.resize(i+1,1.0F);a.lookAtTarget[i]=c.pivot+t;a.cameraVisibility[i]=visibility;}void AnimateAllCameras(CAnim&a){if(a.hdata)for(unsigned i=0;i<a.hdata->cameraObjs.size();++i)AnimateCamera(a,i);}void AnimAnimateCameras(CAnim&a){AnimateAllCameras(a);}
void AnimateTextureMap(CAnim&a,unsigned i){if(!a.hdata||i>=a.hdata->tex.size()||a.primarySeq>=a.seq.size())return;if(i>=a.textureStatus.size())a.textureStatus.resize(i+1);auto&t=a.hdata->tex[i];auto&s=a.textureStatus[i];NTempest::C3Vector tr{},sc{1};NTempest::C4Quaternion q;const bool translated=SampleTrack(t.translation,a,tr,&s.translation),scaled=SampleTrack(t.scale,a,sc,&s.scale),rotated=SampleTrack(t.rotation,a,q,&s.rotation);NTempest::C34Matrix matrix;if(scaled)matrix.Scale(sc);if(rotated)matrix.Rotate(q);if(translated)matrix.Translate(tr);s.transform=matrix;}void AnimateAllTextureMaps(CAnim&a){if(a.hdata)for(unsigned i=0;i<a.hdata->tex.size();++i)AnimateTextureMap(a,i);}void AnimateAllGeosets(CAnim&a){if(!a.hdata)return;if(a.geosetStatus.size()<a.hdata->geo.size())a.geosetStatus.resize(a.hdata->geo.size());for(unsigned i=0;i<a.hdata->geo.size();++i)a.geosetStatus[i]=CalcGeosetColor(a,a.hdata->geo[i]);}void AnimateAllMaterialLayers(CAnim&a){if(!a.hdata)return;if(a.layerStatus.size()<a.hdata->layers.size())a.layerStatus.resize(a.hdata->layers.size());for(unsigned i=0;i<a.hdata->layers.size();++i){auto&layer=a.hdata->layers[i];auto&status=a.layerStatus[i];SampleTrack(layer.visibility,a,status.alpha,&status.visibility);SampleTrack(layer.flip,a,status.flip,&status.flipIndex);}}
void RotateTexture(NTempest::C34Matrix&m,float angle){m*=NTempest::C34Matrix::Rotation({0,0,1},angle,true);}void ScaleTexture(NTempest::C34Matrix&m,const NTempest::C3Vector&s){m.Scale(s);}void TranslateTexture(NTempest::C34Matrix&m,const NTempest::C3Vector&t){m.Translate(t);}void RotateViewBillboarded(NTempest::C34Matrix&m){NTempest::C3Vector p{m.d0,m.d1,m.d2};m={};m.d0=p.x;m.d1=p.y;m.d2=p.z;}void RotateViewXAxisBillboarded(NTempest::C34Matrix&m){NTempest::C3Vector x{m.a0,m.a1,m.a2},p{m.d0,m.d1,m.d2};m={};m.a0=x.x;m.a1=x.y;m.a2=x.z;m.d0=p.x;m.d1=p.y;m.d2=p.z;}void RotateViewYAxisBillboarded(NTempest::C34Matrix&m){NTempest::C3Vector y{m.b0,m.b1,m.b2},p{m.d0,m.d1,m.d2};m={};m.b0=y.x;m.b1=y.y;m.b2=y.z;m.d0=p.x;m.d1=p.y;m.d2=p.z;}void RotateViewZAxisBillboarded(NTempest::C34Matrix&m){NTempest::C3Vector z{m.c0,m.c1,m.c2},p{m.d0,m.d1,m.d2};m={};m.c0=z.x;m.c1=z.y;m.c2=z.z;m.d0=p.x;m.d1=p.y;m.d2=p.z;}
NTempest::C3Vector FaceDirection(const NTempest::C3Vector&from,const NTempest::C3Vector&to){auto d=to-from;if(d.SquaredMag()>0)d.Normalize();return d;}void ApplyFaceDir(NTempest::C34Matrix&m,const NTempest::C3Vector&dir){auto f=dir;if(f.SquaredMag()==0)return;f.Normalize();const float angle=std::atan2(f.y,f.x);if(std::fabs(angle)>2.3841858e-7F)m*=NTempest::C34Matrix::Rotation({0,0,1},angle,true);}NTempest::C4Quaternion LookAtPoint(const NTempest::C3Vector&from,const NTempest::C3Vector&to){auto d=FaceDirection(from,to);NTempest::C4Quaternion q;q.FromAngleAxis(std::atan2(d.y,d.x),{0,0,1});return q;}void ApplyLookAt(NTempest::C34Matrix&m,const NTempest::C3Vector&t){NTempest::C3Vector p{m.d0,m.d1,m.d2};m.Rotate(LookAtPoint(p,t));}
